head.b:skin:
body {
  font-family: 'Cairo', sans-serif;
  margin: 0;
  padding: 0;
  background-color: #FAF9F5;
  color: #1e293b;
  direction: rtl;
}
.pulse-glow {
  box-shadow: 0 0 0 0 rgba(5, 150, 105, 0.4);
  animation: pulseGlow 2s infinite;
}
@keyframes pulseGlow {
  0% { box-shadow: 0 0 0 0 rgba(5, 150, 105, 0.4); }
  70% { box-shadow: 0 0 0 12px rgba(5, 150, 105, 0); }
  100% { box-shadow: 0 0 0 0 rgba(5, 150, 105, 0); }
}
/* إخفاء إضافات بلوجر الافتراضية لعرض صفحة الهبوط باحترافية */
#navbar-iframe, .navbar, .header-widget, .blog-pager, .feed-links, .post-feeds {
  display: none !important;
}

body.script:
    //
    const WHATSAPP_NUMBER = '201280254014';

    const PRODUCTS = [
      {
        id: 'green',
        name: 'الأخضر الملكي (نقشة الكعبة المشرفة)',
        colorName: 'أخضر زمردي مع ذهبي',
        colorHex: '#0d4a36',
        badge: 'الأكثر طلباً ⭐',
        flat: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/image_6984cbde.png',
        inUse: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/image_7c2ab4e4.png',
      },
      {
        id: 'teal',
        name: 'التركواز الراقي (المحراب الأندلسي)',
        colorName: 'أبيض مع تركواز بحري',
        colorHex: '#0d766e',
        badge: 'تصميم أندلسي ✨',
        flat: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/image_8910c805.png',
        inUse: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/image_673908e1.png',
      },
      {
        id: 'beige',
        name: 'البيج الكشميري (نقش الزهور الهادئة)',
        colorName: 'كشمير بيج دافئ',
        colorHex: '#b58b6f',
        badge: 'ألوان هادئة 🌿',
        flat: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/image_3c676ddb.png',
        inUse: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/image_2e70afcc.png',
      },
      {
        id: 'rose',
        name: 'الوردي الهادئ (المشكاة المخملية)',
        colorName: 'وردي ناعم مع أبيض',
        colorHex: '#df899f',
        badge: 'هدية مميزة 🎁',
        flat: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/image_4c330914.png',
        inUse: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/image_05db635a.png',
      },
      {
        id: 'navy',
        name: 'الكحلي البترولي (المحراب الذهبي)',
        colorName: 'كحلي داكن مع تطريز ذهبي',
        colorHex: '#1e384b',
        badge: 'فخامة ملكية 👑',
        flat: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/Edit_prayer_rug_image_white_2K_20261025223506_978f82d7.jpg',
        inUse: 'https://ais-pre-ts5axkesjombi5mkolod5c-185137071279.europe-west3.run.app/assets/aistudio/Woman_praying_on_prayer_rug_2K_20261025212442_fe21e9da.jpg',
      }
    ];

    let currentSelectedProduct = PRODUCTS[0];
    let currentQuantity = 1;
    let currentHeroView = 'inUse';

    function renderHeroColors() {
      const container = document.getElementById('hero-color-buttons');
      if (!container) return;
      container.innerHTML = '';
      PRODUCTS.forEach(p => {
        const isSel = p.id === currentSelectedProduct.id;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `p-1.5 rounded-xl border text-center transition-all flex flex-col items-center ${isSel ? 'border-emerald-600 bg-emerald-50 ring-2 ring-emerald-500/20' : 'border-slate-200 bg-slate-50'}`;
        btn.onclick = () => selectProduct(p);
        btn.innerHTML = `
          <div class="w-10 h-14 rounded overflow-hidden border border-slate-200 mb-1">
            <img src="${p.flat}" class="w-full h-full object-cover" />
          </div>
          <span class="text-[10px] font-bold line-clamp-1">${p.name.split('(')[0].trim()}</span>
          <span class="w-3 h-3 rounded-full mt-1 border border-white" style="background:${p.colorHex}"></span>
        `;
        container.appendChild(btn);
      });
    }

    function renderFormColors() {
      const container = document.getElementById('form-color-buttons');
      if (!container) return;
      container.innerHTML = '';
      PRODUCTS.forEach(p => {
        const isSel = p.id === currentSelectedProduct.id;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `p-2 rounded-xl border text-center transition-all flex flex-col items-center ${isSel ? 'border-2 border-emerald-600 bg-emerald-50' : 'border-slate-200 hover:border-slate-300'}`;
        btn.onclick = () => selectProduct(p);
        btn.innerHTML = `
          <div class="w-12 h-16 rounded-lg overflow-hidden border border-slate-200 mb-1">
            <img src="${p.flat}" class="w-full h-full object-cover" />
          </div>
          <span class="text-[10px] font-bold line-clamp-1">${p.name.split('(')[0].trim()}</span>
          <span class="w-3 h-3 rounded-full mt-1 border border-white" style="background:${p.colorHex}"></span>
        `;
        container.appendChild(btn);
      });
    }

    function selectProduct(p) {
      currentSelectedProduct = p;
      const heroBadge = document.getElementById('hero-badge');
      if (heroBadge) heroBadge.innerText = p.badge;
      const modelTitle = document.getElementById('hero-model-title');
      if (modelTitle) modelTitle.innerText = p.name;
      updateHeroImage();
      renderHeroColors();
      renderFormColors();
    }

    function changeHeroView(view) {
      currentHeroView = view;
      const btnInUse = document.getElementById('btn-view-inUse');
      const btnFlat = document.getElementById('btn-view-flat');
      if (btnInUse) btnInUse.className = view === 'inUse' ? 'flex-1 py-1 rounded bg-white text-emerald-800 shadow-xs' : 'flex-1 py-1 rounded hover:text-emerald-800';
      if (btnFlat) btnFlat.className = view === 'flat' ? 'flex-1 py-1 rounded bg-white text-emerald-800 shadow-xs' : 'flex-1 py-1 rounded hover:text-emerald-800';
      updateHeroImage();
    }

    function updateHeroImage() {
      const img = document.getElementById('hero-main-img');
      if (!img) return;
      img.src = currentHeroView === 'inUse' ? currentSelectedProduct.inUse : currentSelectedProduct.flat;
    }

    function updateBundle(qty) {
      currentQuantity = qty;
      const subtotal = qty * 369;
      const shipping = qty >= 2 ? 0 : 65;
      const total = subtotal + shipping;

      document.getElementById('summary-subtotal').innerText = subtotal + ' جنيه (' + qty + ' قطع)';
      document.getElementById('summary-shipping').innerText = shipping === 0 ? 'مجاناً 🚚' : '65 جنيه';
      document.getElementById('summary-total').innerText = total + ' جنيه';
    }

    function handleBloggerOrder(e) {
      e.preventDefault();

      const name = document.getElementById('cust-name').value.trim();
      const phone = document.getElementById('cust-phone').value.trim();
      const gov = document.getElementById('cust-gov').value;
      const address = document.getElementById('cust-address').value.trim();
      const notes = document.getElementById('cust-notes').value.trim();

      const subtotal = currentQuantity * 369;
      const shipping = currentQuantity >= 2 ? 0 : 65;
      const total = subtotal + shipping;
      const orderNo = 'ORD-' + Math.floor(100000 + Math.random() * 900000);

      const msg = `السلام عليكم ورحمة الله،
أرغب في تأكيد طلب مصلية الصلاة الطبية:
• رقم الأوردر: ${orderNo}
• الكمية: ${currentQuantity} ${currentQuantity === 1 ? 'مصلية' : 'مصليات'}
• السعر: ${subtotal} جنيه
• مصاريف الشحن: ${shipping === 0 ? 'مجاناً 🚚' : '65 جنيه'}
• الإجمالي عند الاستلام: ${total} جنيه
• اللون والنقشة: ${currentSelectedProduct.name}
• الاسم: ${name}
• الهاتف: ${phone}
• المحافظة: ${gov}
• العنوان بالتفصيل: ${address}
${notes ? `• ملاحظات: ${notes}` : ''}

(الدفع عند الاستلام بعد المعاينة والفحص)`;

      const waUrl = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(msg)}`;
      window.location.href = waUrl;
    }

    // التهيئة التلقائية
    renderHeroColors();
    renderFormColors();
    updateBundle(1);
    //
